import { memo } from 'react';
import { createRoot } from 'react-dom/client';
import {
  ComboBox,
  Input,
  Label,
  ListBox,
  ListBoxItem,
  Popover,
} from 'react-aria-components';

type Source = 'incoming' | 'outgoing';
type StudyRecord = { id: number; label: string };
type Mark = (kind: 'row') => void;

const fruits = [
  { id: 'Apricot', name: 'Apricot' },
  { id: 'Blueberry', name: 'Blueberry' },
  { id: 'Cherry', name: 'Cherry' },
];

const Row = memo(function Row({ id, label, selected, mark }: {
  id: number;
  label: string;
  selected: boolean;
  mark: Mark;
}) {
  mark('row');
  return (
    <div data-row={id} aria-selected={selected ? 'true' : 'false'}>
      <span>{label}</span>
      <input aria-label={`Edit record ${id}`} defaultValue={label} />
    </div>
  );
});

function FruitPicker({ onCommit }: { onCommit: (value: string) => void }) {
  return (
    <ComboBox
      defaultItems={fruits}
      onSelectionChange={(key) => {
        if (typeof key === 'string') onCommit(key);
      }}
    >
      <Label>Fruit</Label>
      <Input />
      <Popover>
        <ListBox>
          {(fruit) => <ListBoxItem id={fruit.id}>{fruit.name}</ListBoxItem>}
        </ListBox>
      </Popover>
    </ComboBox>
  );
}

export function mountStudy(
  root: HTMLElement,
  onCommit: (value: string) => void,
  mark: Mark,
) {
  const app = createRoot(root);
  const counts: Record<Source, number> = { incoming: 4, outgoing: 7 };
  let active: Source = 'incoming';
  let records: StudyRecord[] = [
    { id: 1, label: 'One' },
    { id: 2, label: 'Two' },
    { id: 3, label: 'Three' },
    { id: 4, label: 'Four' },
  ];
  let selected = 1;
  let pickerOpen = false;
  let pickerKey = 0;
  let disposed = false;

  function render() {
    if (disposed) return;
    const badge = `${counts[active]} crates`;
    const currentPickerKey = pickerKey;
    app.render(
      <>
        <div>
          <output data-badge="" title={badge}>{badge}</output>
          <input data-note="" aria-label="Note" />
        </div>
        <div>
          {records.map(({ id, label }) => (
            <Row key={id} id={id} label={label} selected={selected === id} mark={mark} />
          ))}
        </div>
        {pickerOpen && (
          <FruitPicker key={currentPickerKey} onCommit={(value) => {
            if (!disposed && pickerOpen && pickerKey === currentPickerKey) onCommit(value);
          }} />
        )}
      </>,
    );
  }

  render();
  return {
    count(source: Source, value: number) {
      counts[source] = value;
      if (source === active) render();
    },
    mode(source: Source) {
      active = source;
      render();
    },
    select(id: number) {
      selected = id;
      render();
    },
    refetch(nextRecords: StudyRecord[]) {
      records = nextRecords.slice();
      render();
    },
    swap() {
      if (records.length < 2) return;
      records = [records[1]!, records[0]!, ...records.slice(2)];
      render();
    },
    open() {
      if (pickerOpen || disposed) return;
      pickerOpen = true;
      pickerKey += 1;
      render();
    },
    close() {
      pickerOpen = false;
      render();
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      app.unmount();
    },
  };
}
